use std::env;
use std::io::{self, Write};
use std::process;

#[path = "src/url_parser/mod.rs"]
mod url_parser;

fn write_line<W: Write>(writer: &mut W, bytes: &[u8]) -> io::Result<()> {
    writer.write_all(bytes)?;
    writer.write_all(b"\n")
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        process::exit(1);
    }

    let input = &args[1];
    let encoded = url_parser::url_encode(input);
    let decoded = url_parser::url_decode(input);
    let parser = url_parser::URL::new(format!("http://example.com/test?q={encoded}"));

    let mut stdout = io::stdout().lock();

    writeln!(stdout, "{encoded}").expect("failed to write encoded output");
    write_line(&mut stdout, &decoded).expect("failed to write decoded output");
    writeln!(stdout, "{}", parser.scheme()).expect("failed to write scheme");
    writeln!(stdout, "{}", parser.host()).expect("failed to write host");
    writeln!(stdout, "{}", parser.path()).expect("failed to write path");
    writeln!(stdout, "{}", parser.query()).expect("failed to write query");

    for (key, value) in parser.query_params() {
        let decoded_key = url_parser::url_decode_bytes(&key);
        let decoded_value = url_parser::url_decode_bytes(&value);
        write_line(&mut stdout, &decoded_key).expect("failed to write query key");
        write_line(&mut stdout, &decoded_value).expect("failed to write query value");
    }
}
